query getData($limit: Int!) {
  products_connection(
    first: $limit
    where: {status: {_neq: "1"}}
    order_by: {id: desc}
  ) {
    edges {
      cursor
      node {
        id
        fulfillment_id
        mockups(limit: 2, order_by: {position: asc}) {
          preview_thumbnail
          thumbnail
          __typename
        }
        label
        title
        internal_tags
        is_imported
        campaign_products {
          id
          campaign {
            id
            status
            campaign_instances {
              id
              need_sync
              __typename
            }
            __typename
          }
          __typename
        }
        campaign_products
        created_at
        status
        fulfillment {
          display_name
          __typename
        }
        campaign_products_aggregate {
          aggregate {
            count
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}

